        const element = document.createElement(tag);
        if (className) {
          element.className = className;
        }
        if (typeof text === "string") {
          element.textContent = text;
        }
        return element;
      };

      const QuestionField = (question, index) => {
        const wrapper = createElement("div", "form-field");
